const baseUrlApi = `${source.key}api/comment?pageSize=20&site=${baseUrl.match(/api\/(.*?)$/)[1].replace('novel', 'web').replaceAll('/', '-')}`;

function formatComments(items, parentName) {
    if (!items.length) return '';
    return items.map(item => {
        let time = java.timeFormatUTC(item.createAt * 1000, 'yyyy-MM-dd HH:mm:ss', 0);
        let replyTag = parentName ? ` | @${parentName}` : '';
        let content = (parentName ? 'ㅤ' : '') + item.content;

        let block = `${parentName ? '└' + item.user.username : item.user.username} | ${time}${replyTag}\n${parentName ? content.replaceAll('\n', '\nㅤ') : content}`;

        if (item.replies.length) {
            block += '\n' + formatComments(item.replies, item.user.username, true);
        }
        return block;
    }).join(parentName ? '\n' : '\nㅤ\n');
}

const allComments = [];
let page = 0;
let hasMore = true;

while (hasMore && page < 5) {
    let res = JSON.parse(java.get(`${baseUrlApi}&page=${page}`, {}).body() || '{}');
    if (res.items.length) {
        allComments.push(formatComments(res.items));
        hasMore = page < (res.pageNumber - 1);
        page++;
    } else {
        hasMore = false;
    }
}

const Comment = allComments.length ? `\n💬 [评论区 | 时间倒序]：\n${allComments.join('\nㅤ\n')}`.replaceAll('::: star ', '评分：⭐×').replaceAll('::: details 点击展开', '').replace('\n:::\n', '') : '';

result + Comment;

