function login(){}
function xyLoginState() {
  var state = {};
  try {
    state = JSON.parse(source.getVariable() || "{}");
  } catch (error) {
    state = {};
  }
  if (!state || typeof state !== "object") state = {};
  if (state.xySite === "男站") state.xySite = "男生";
  if (state.xySite === "女站") state.xySite = "女生";
  if (
    state.xySite !== "男生" &&
    state.xySite !== "女生" &&
    state.xySite !== "出版"
  )
    state.xySite = "男生";
  if (!state.xyOrderName || state.xyOrderName === "默认榜单")
    state.xyOrderName = "人气最高";
  if (!state.xyCategoryName) state.xyCategoryName = "全部";
  if (state.xyShowPara !== false) state.xyShowPara = true;
  if (state.xyShowChapter !== false) state.xyShowChapter = true;
  if (state.xyLargeBubble !== false) state.xyLargeBubble = true;
  if (state.xyFullComment !== true) state.xyFullComment = false;
  if (state.xyCustomMode !== true) state.xyCustomMode = false;
  state.xyYwkey = String(state.xyYwkey || "");
  state.xyYwguid = String(state.xyYwguid || "");
  state.xyUserToken = String(state.xyUserToken || "");
  state.xyGuestAuthor = String(state.xyGuestAuthor || "");
  state.xyGuestGroup = String(state.xyGuestGroup || "");
  state.xyGuestPass = String(state.xyGuestPass || "");
  state.xyGuestVerified = state.xyGuestVerified === true;
  state.xyAndroidId = String(state.xyAndroidId || "");
  state.xyUserName = String(state.xyUserName || "");
  state.xyUserLevel = String(state.xyUserLevel || "");
  return state;
}

function xyLoginSave(state) {
  source.setVariable(JSON.stringify(state));
  try {
    java.reLoginView();
  } catch (error) {}
}


function xyLoginAndroidId(state) {
  var value = "";
  try { value = String(java.androidId() || "").replace(/^\s+|\s+$/g, ""); } catch (error) {}
  if (!value) value = String((state && state.xyAndroidId) || "").replace(/^\s+|\s+$/g, "");
  if (!value) {
    var chars = "0123456789abcdef";
    for (var index = 0; index < 16; index++) value += chars.charAt(Math.floor(Math.random() * 16));
  }
  return value.toUpperCase();
}
function xyLoginRequest(action, data) {
  var options = {method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(data || {})};
  var response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=" + action + "," + JSON.stringify(options)));
  if (response.error) throw new Error(response.error);
  return response;
}
function xyLoginStoreAuth(state, response, androidId) {
  var user = response.user || {};
  state.xyAndroidId = String(androidId || xyLoginAndroidId(state));
  state.xyUserToken = String(response.token || "");
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  state.xyCustomMode = false;
  xyLoginSave(state);
  return user;
}
function xyLoginGuest() {
  var state = xyLoginState();
  var sourceAuthor = xyLoginFieldValue("源作者");
  var feedbackGroup = xyLoginFieldValue("官方反馈群");
  var temporaryPassword = xyLoginFieldValue("临时口令");
  state.xyGuestAuthor = sourceAuthor;
  state.xyGuestGroup = feedbackGroup;
  state.xyGuestPass = temporaryPassword;
  source.setVariable(JSON.stringify(state));
  xyLoginSaveGuestFields(sourceAuthor, feedbackGroup, temporaryPassword);
  if (!sourceAuthor || !feedbackGroup || !temporaryPassword)
    return java.toast("请手动填写源作者、官方反馈群和临时口令");
  var androidId = xyLoginAndroidId(state);
  var response;
  try {
    response = xyLoginRequest("guest", {
      source_author: sourceAuthor,
      feedback_group: feedbackGroup,
      temporary_password: temporaryPassword,
      android_id: androidId
    });
  } catch (error) {
    return java.toast(String((error && error.message) || error));
  }
  state.xyGuestVerified = true;
  var user = xyLoginStoreAuth(state, response, androidId);
  java.toast("游客授权成功：" + String(user.privilege || ""));
}
function xyLoginFieldValue(name) {
  return String((result && result.get(name)) || "").replace(/^\s+|\s+$/g, "");
}

function xyLoginSaveGuestFields(sourceAuthor, feedbackGroup, temporaryPassword) {
  try {
    var loginInfo = {};
    try {
      loginInfo = JSON.parse(source.getLoginInfo() || "{}");
    } catch (error) {}
    loginInfo["源作者"] = sourceAuthor;
    loginInfo["官方反馈群"] = feedbackGroup;
    loginInfo["临时口令"] = temporaryPassword;
    source.putLoginInfo(JSON.stringify(loginInfo));
    try {
      java.upLoginData(loginInfo);
    } catch (error) {}
  } catch (error) {}
}

function xyLoginWeb() { 
  var state = xyLoginState();
  var androidId = xyLoginAndroidId(state);
  state.xyAndroidId = androidId;
  xyLoginSave(state);
  var preload = [
    "window.xySaveLegadoAuth = function(payload) {",
    "  var state = {};",
    "  try { state = JSON.parse(source.getVariable() || '{}'); } catch (error) { state = {}; }",
    "  var user = (payload && payload.user) || {};",
    "  state.xyUserToken = String((payload && payload.token) || '');",
    "  state.xyAndroidId = String((payload && payload.android_id) || state.xyAndroidId || '');",
    "  state.xyUserName = String(user.username || '');",
    "  state.xyUserLevel = String(user.level || 'guest');",
    "  state.xyCustomMode = false;",
    "  var encoded = JSON.stringify(state);",
    "  try { source.putVariable(encoded); } catch (error) { try { source.setVariable(encoded); } catch (ignored) {} }",
    "  setTimeout(function(){ try { if (java.reLoginView) java.reLoginView(true); } catch (error) {} try { window.close(); } catch (error) {} }, 1500);",
    "  return true;",
    "};"
  ].join("\n");
  java.showBrowser(XY_API_ROOT + "auth.php?mode=legado&android_id=" + encodeURIComponent(androidId), null, preload);

}
function xyLoginUserCenter() {
  var state = xyLoginState();
  var token = String(state.xyUserToken || "");
  var androidId = String(state.xyAndroidId || "");
  var preload = [
    "try { localStorage.setItem('qidian-user-token', " + JSON.stringify(token) + "); } catch (e) {}",
    "try { localStorage.setItem('qidian-android-id', " + JSON.stringify(androidId) + "); } catch (e) {}"
  ].join("\n");
  try { java.showBrowser(XY_API_ROOT + "account.php", null, preload); }
  catch (error) { java.toast("无法打开用户中心：" + String(error)); }
}
function xyLoginSyncAuth() {
  var state = xyLoginState();
  if (!state.xyUserToken) {
    xyLoginSave(state);
    java.toast("当前尚未授权");
    return;
  }
  var options = {method:"GET",headers:{Accept:"application/json","X-Sec-Token":state.xyUserToken,"X-Android-Id":state.xyAndroidId}};
  var response;
  try {
    response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=me," + JSON.stringify(options)));
  } catch (error) {
    xyLoginSave(state);
    java.toast("授权状态同步失败，请稍后重试");
    return;
  }
  if (response.error) {
    state.xyUserToken = "";
    state.xyUserName = "";
    state.xyUserLevel = "";
    state.xyGuestVerified = false;
    xyLoginSave(state);
    java.toast("授权已失效，请重新登录");
    return;
  }
  var user = response.user || {};
  state.xyUserToken = String(response.token || state.xyUserToken);
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  xyLoginSave(state);
  java.toast("授权状态已同步：" + (user.username || "游客用户"));
}
function xyLoginUsage() {
  var state = xyLoginState();
  if (!state.xyUserToken) return java.toast("请先申请游客 Token 或登录账号");
  var options = {method:"GET",headers:{Accept:"application/json","X-Sec-Token":state.xyUserToken,"X-Android-Id":state.xyAndroidId}};
  var response = JSON.parse(java.ajax(XY_API_ROOT + "user_api.php?action=me," + JSON.stringify(options)));
