function xyNormalizeBase64(value) {
  var encoded = String(value || "").replace(/\s+/g, "");
  encoded = encoded.replace(/-/g, "+").replace(/_/g, "/");
  while (encoded.length % 4) encoded += "=";
  return encoded;
}

function xyDecodeChapter(ctx, value) {
  var text = String(value || "");
  try {
    text = decodeURIComponent(text);
  } catch (error) {}
  if (text.charAt(0) === "{") return JSON.parse(text);
  var match = text.match(/base64,([A-Za-z0-9+\/=_%-]+)/i);
  var encoded = match ? match[1] : text;
  if (!encoded) throw new Error("章节地址无效");
  var separator = encoded.indexOf(",");
  if (separator >= 0) encoded = encoded.substring(0, separator);
  var json = xyBridge(ctx).base64Decode(xyNormalizeBase64(encoded));
  var data = JSON.parse(json);
  if (
    !data ||
    !data.bookId ||
    data.chapterId === undefined ||
    data.chapterId === null ||
    data.chapterId === ""
  ) {
    throw new Error("章节信息无效");
  }
  if (
    !Object.prototype.hasOwnProperty.call(data, "time") ||
    !/^\d+$/.test(String(data.time))
  ) {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  if (String(data.time) === "0") {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  return data;
}

function xyChapterPayload(ctx, value) {
