function xyCleanText(value) {
  var images = [];
  var text = String(value || "").replace(/<img\b[^>]*>/gi, function (tag) {
    images.push(tag);
    return "\n@@XY_IMG_" + (images.length - 1) + "@@\n";
  });
  text = text
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\r\n?/g, "\n");
  return text.replace(/@@XY_IMG_(\d+)@@/g, function (all, index) {
    return images[Number(index)] || "";
  });
