function xyCommentCounts(ctx, bookId, chapterId) {
  var map = {};
  var chapterCount = 0;
  try {
    var response = xyJson(
      ctx,
      XY_API_ROOT +
        "review.php?bookId=" +
        encodeURIComponent(String(bookId)) +
        "&chapterId=" +
        encodeURIComponent(String(chapterId)),
    );
    var root = response.data || response.Data || {};
    var list = (root.Getparagraphscommentcounts || {}).DataList || [];
    for (var index = 0; index < list.length; index++) {
      var item = list[index];
      var paragraph = Number(item.ParagraphId);
      var count = Number(item.CommentCount);
      if (paragraph === -1) {
        chapterCount = count;
      } else if (paragraph >= 0 && count > 0) {
        map[String(paragraph)] = {
          count: count,
          hot: Number(item.HasHotComment || item.hasHotComment || 0) === 1,
        };
