    '<text x="' +
    left +
    '" y="88" font-size="46" font-family="Segoe UI,Arial,sans-serif" fill="#333333">本章说</text>' +
    '<text x="' +
    (width - right) +
    '" y="86" font-size="38" text-anchor="end" font-family="Segoe UI,Arial,sans-serif" fill="#666666">' +
    xyXmlEscape(Number(count) + "条评论 ❯") +
