function xyFormatContent(ctx, body, baseUrl) {
  var response;
  try {
    response = JSON.parse(body);
  } catch (error) {
    throw new Error("正文响应不是JSON：" + String(body).substring(0, 120));
  }
  if (response.error) throw new Error(response.error);
  if (response.detail) throw new Error(response.detail);
  if (
    response.code !== undefined &&
    Number(response.code) !== 0 &&
    response.msg
  )
    throw new Error(response.msg);

  var content =
    response.content ||
    response.Content ||
    (response.Data && response.Data.Content) ||
    "";
  if (!content) throw new Error("正文内容为空");

  var bookId = xyQuery(ctx, baseUrl, "bookId");
  var chapterId = xyQuery(ctx, baseUrl, "chapterId");
  var state = xyState(ctx);
  var counts =
    state.xyShowPara || state.xyShowChapter
      ? xyCommentCounts(ctx, bookId, chapterId)
      : { map: {}, chapter: 0 };
  var lines = xyCleanText(content).split("\n");
  var output = [];
  var paragraphIndex = 1;

  for (var index = 0; index < lines.length; index++) {
    var line = lines[index].replace(/^\s+|\s+$/g, "");
    if (!line) continue;
    if (/<img\b/i.test(line)) {
      output.push(line);
      continue;
    }
    var idea = counts.map[String(paragraphIndex)];
    if (
      state.xyShowPara &&
      idea &&
      idea.count > 0 &&
      line.indexOf(
        "xyComment:" + bookId + ":" + chapterId + ":" + paragraphIndex,
      ) < 0
    ) {
      line +=
        " " +
        xyCommentBubble(
          ctx,
          idea.count,
          bookId,
          chapterId,
          paragraphIndex,
          idea.hot,
        );
    }
    output.push(line);
    paragraphIndex++;
  }

  if (state.xyShowChapter) {
    var card = xyCommentCard(ctx, counts.chapter, bookId, chapterId);
    if (card) output.push("", card);
  }
  return output.join("\n");
}
function xySearchItems(ctx, body) {
  var response = JSON.parse(body);
  var cards = (response.Data || {}).CardList || [];
  var output = [];
  for (var cardIndex = 0; cardIndex < cards.length; cardIndex++) {
    var rows = cards[cardIndex].Body || [];
    for (var rowIndex = 0; rowIndex < rows.length; rowIndex++) {
      var item = rows[rowIndex].ItemData;
      if (item && Number(item.BookId) > 0 && Number(item.BookType) === 1) {
        output.push(JSON.stringify(item));
      }
    }
  }
  return output;
}

function xyExploreItems(ctx, body) {
  var list = (JSON.parse(body).Data || {}).Books || [];
  var output = [];
  for (var index = 0; index < list.length; index++)
    output.push(JSON.stringify(list[index]));
  return output;
}

function xyKind(data) {
  var values = [
    data.CategoryName,
    data.SubCategoryName,
    data.ActionStatusString,
    data.BookStatus,
    data.WordsCount,
  ];
  var tags = data.BookTags || [];
  for (var tagIndex = 0; tagIndex < tags.length && tagIndex < 4; tagIndex++)
    values.push(tags[tagIndex]);
  var output = [];
  for (var index = 0; index < values.length; index++) {
    var value = String(values[index] || "").replace(/^\s+|\s+$/g, "");
    if (value && value !== "0") output.push(value);
  }
  return output.join("·");
}

function xyFallbackConfig() {
  return {
    sites: [
      { Id: 11, Name: "男生" },
      { Id: 12, Name: "女生" },
      { Id: 4, Name: "出版" },
    ],
    orders: [{ Id: 11, Name: "人气最高" }],
    lines: [],
    filterOne: [],
    valid: false,
  };
}

function xyConfigLine(lines, tag) {
  for (var index = 0; index < (lines || []).length; index++) {
    if (lines[index].Tag === tag) return lines[index];
  }
  return {};
}

function xyOptions(line) {
  return line && line.FilterUnions ? line.FilterUnions : [];
}

function xyNames(options) {
  var output = [];
  for (var index = 0; index < (options || []).length; index++)
    output.push(String(options[index].Name));
  return output;
}

function xySelected(options, name) {
  for (var index = 0; index < (options || []).length; index++) {
    if (String(options[index].Name) === String(name)) return options[index];
  }
  return options && options.length ? options[0] : null;
}

function xyOptional(options, name) {
  if (!name) return null;
  for (var index = 0; index < (options || []).length; index++) {
    if (String(options[index].Name) === String(name)) return options[index];
  }
  return null;
}

function xyOptionId(options, name, fallback) {
  var selected = xySelected(options, name);
  return selected && selected.Id !== undefined ? selected.Id : fallback;
}

function xyLoadConfig(ctx, state) {
  var config = xyFallbackConfig();
  var siteId = xyOptionId(config.sites, state.xySite, 11);
  try {
    var response = xyJson(
      ctx,
      XY_API_ROOT + "ranking.php?action=config&site_id=" + siteId,
    );
    var data = response.Data || response.data || {};
    var resultCode =
      response.Result !== undefined
        ? Number(response.Result)
        : Number(response.result || 0);
    if (resultCode === 0 && data) {
      var sites = (data.SiteList || []).filter(function (item) {
        return XY_TEXT_SITES[String(Number(item.Id))] === 1;
      });
      if (sites.length) config.sites = sites;
      config.orders = data.Orders || [];
      config.lines = data.FiltrLines || [];
      config.filterOne = data.FilterOne || [];
      config.valid = true;
    }
  } catch (error) {
    try {
      xyBridge(ctx).log("发现配置加载失败：" + error);
    } catch (ignored) {}
  }
  if (!config.orders.length) config.orders = xyFallbackConfig().orders;
  return config;
}

function xySelectAction(key, title, clearKeys, syncInfo) {
  var clear = "";
  if (clearKeys && clearKeys.length) {
    for (var index = 0; index < clearKeys.length; index++) {
      clear += "delete d[" + JSON.stringify(clearKeys[index]) + "];";
    }
  }
  var sync = syncInfo
    ? "xySyncExploreInfo(infoMap, " + JSON.stringify(syncInfo) + ");"
    : "";
  return (
    "var v=infoMap[" +
    JSON.stringify(title) +
    "]||(infoMap.get&&infoMap.get(" +
    JSON.stringify(title) +
    "));var d={};try{d=JSON.parse(source.getVariable()||'{}')}catch(e){}" +
    clear +
    "d." +
    key +
    "=String(v||'');source.setVariable(JSON.stringify(d));" +
    sync +
    "try{source.refreshExplore()}catch(e){}try{java.refreshExplore()}catch(e){}"
  );
}

function xyHeader(rows, title) {
  rows.push({
    title: "—— " + title + " ——",
    url: "",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 },
  });
}

function xyEntry(rows, title, url, basis) {
  rows.push({
    title: title,
    url: url,
    style: {
      layout_flexGrow: 1,
      layout_flexBasisPercent: basis === undefined ? -1 : basis,
    },
  });
}

function xyActionButton(rows, title, action, basis) {
  rows.push({
    title: title,
    url: "",
    type: "button",
    action: action,
    style: {
      layout_flexGrow: 1,
      layout_flexBasisPercent: basis === undefined ? -1 : basis,
    },
  });
}

function xyChip(rows, title, url, selected) {
  rows.push({
    title: (selected ? "✅ " : "") + title,
    url: url,
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 },
  });
}

function xySelect(rows, title, options, selected, action, viewName) {
  var row = {
    title: title,
    url: "",
    type: "select",
    chars: xyNames(options),
    default: String(selected ? selected.Name : ""),
    action: action,
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.45 },
  };
  if (viewName) row.viewName = "'" + viewName + "'";
  rows.push(row);
}

function xyFilterTitle(tag) {
  return XY_FILTER_TITLES[tag] || tag;
}

function xyQueryName(tag) {
  return XY_QUERY_NAMES[tag] || tag;
}

function xyWithState(state, key, value) {
  var next = {};
  for (var name in state) {
    if (Object.prototype.hasOwnProperty.call(state, name))
      next[name] = state[name];
  }
  if (value === undefined || value === null || value === "") delete next[key];
  else next[key] = String(value);
  return next;
}

function xyBlankOptions(options) {
  return [{ Name: "不限" }].concat(options || []);
}

function xySelectedOption(line, name) {
  if (!name || name === "不限") return null;
  return xyOptional(xyOptions(line), name);
}

function xySelectedFilterOne(config, state, tag) {
  var lines = config.filterOne || [];
  for (var index = 0; index < lines.length; index++) {
    if (lines[index].Tag !== tag) continue;
    var name = tag === "great" ? state.xyGreatName : state.xyEndureName;
    return xySelectedOption(lines[index], name);
  }
  return null;
}

function xySelectedTag(config, state) {
  var groups = xyOptions(xyConfigLine(config.lines, "classid"));
  var value = String(state.xyTagValue || "");
  for (var groupIndex = 0; groupIndex < groups.length; groupIndex++) {
    var group = groups[groupIndex];
    var tags = group.Extvalue || [];
    for (var tagIndex = 0; tagIndex < tags.length; tagIndex++) {
      if (value === String(group.Id) + ":" + String(tags[tagIndex].Id)) {
        return { id: String(tags[tagIndex].Id), classId: String(group.Id) };
      }
    }
  }
  return null;
}

function xyResetExtendedState(state) {
  var next = {};
  for (var key in state) {
    if (!Object.prototype.hasOwnProperty.call(state, key)) continue;
    if (
      key === "xyActionStatusName" ||
      key === "xyWordsCountName" ||
      key === "xyPaidModeName" ||
      key === "xyTagTypeName" ||
      key === "xyGreatName" ||
      key === "xyEndureName" ||
      key === "xyTagValue" ||
      /^xyTag_/.test(key) ||
      /^xyFilterOne_/.test(key)
    )
      continue;
    next[key] = state[key];
  }
  return next;
}

function xySyncExploreInfo(infoMap, values) {
  if (!infoMap) return;
  for (var name in values) {
    if (!Object.prototype.hasOwnProperty.call(values, name)) continue;
    var value = values[name];
    try {
      if (value === undefined || value === null || value === "")
        infoMap.remove(name);
      else infoMap.put(name, String(value));
    } catch (error) {}
  }
  try {
    infoMap.saveNow();
  } catch (error) {}
}

function xyResetMainExploreState(state) {
  var next = {};
  for (var key in state) {
    if (!Object.prototype.hasOwnProperty.call(state, key)) continue;
    if (
      key === "xySite" ||
      key === "xyOrderName" ||
      key === "xyCategoryName" ||
      key === "xySubCategoryName"
    )
      continue;
    next[key] = state[key];
  }
  return next;
}

function xyResetMainExploreFilters(holder, bridge, infoMap) {
  holder.setVariable(
    JSON.stringify(xyResetMainExploreState(xyState({ source: holder }))),
  );
  xySyncExploreInfo(infoMap, {
    站点: "男生",
    榜单: "人气最高",
    分类: "全部",
    子分类: null,
  });
  try {
    holder.refreshExplore();
  } catch (error) {}
  try {
    bridge.refreshExplore();
  } catch (error) {}
}

function xyResetExtendedExploreFilters(holder, bridge, infoMap) {
  holder.setVariable(
    JSON.stringify(xyResetExtendedState(xyState({ source: holder }))),
  );
  xySyncExploreInfo(infoMap, {
    连载状态: "不限",
    字数范围: "不限",
    付费模式: "不限",
    标签匹配: "包含任意已选标签",
    精品: "不限",
    耐看: "不限",
  });
  try {
    holder.refreshExplore();
  } catch (error) {}
  try {
    bridge.refreshExplore();
  } catch (error) {}
}

function xyRankingUrl(config, state, page, extra) {
  var site = xySelected(config.sites, state.xySite);
  var order = xySelected(config.orders, state.xyOrderName);
  var categoryLine = xyConfigLine(config.lines, "categoryid");
  var categories = xyOptions(categoryLine);
  var category = xySelected(categories, state.xyCategoryName);
  var subcategory = xyOptional(
    category && category.Extvalue,
    state.xySubCategoryName,
  );
  var actionStatus = xySelectedOption(
    xyConfigLine(config.lines, "actionstatus"),
    state.xyActionStatusName,
  );
  var wordsCount = xySelectedOption(
    xyConfigLine(config.lines, "wordscount"),
    state.xyWordsCountName,
  );
  var paidMode = xySelectedOption(
    xyConfigLine(config.lines, "paidmode"),
    state.xyPaidModeName,
  );
  var selectedTag = xySelectedTag(config, state);
  var tagType = selectedTag
    ? xySelectedOption(
        xyConfigLine(config.lines, "tagtype"),
        state.xyTagTypeName,
      )
    : null;
  var great = xySelectedFilterOne(config, state, "great");
  var endure = xySelectedFilterOne(config, state, "endure");

  var params = {
    action: "ranking",
    site_id: String(site ? site.Id : 11),
    order: String(order ? order.Id : 11),
    page: String(page),
    page_size: "20",
    category_id: String(category ? category.Id : 0),
  };
  if (
    subcategory &&
    subcategory.Id !== undefined &&
    String(subcategory.Id) !== "0"
  ) {
    params.subcategory_id = String(subcategory.Id);
  }
  if (actionStatus) params.action_status = String(actionStatus.Id);
  if (wordsCount) params.words_count = String(wordsCount.Id);
  if (paidMode) params.paid_mode = String(paidMode.Id);
  if (selectedTag) {
    params.class_id = selectedTag.classId;
    params.tag_ids = selectedTag.id;
  }
  if (tagType) params.tag_type = String(tagType.Id);
  if (great) params.great = String(great.Id);
  if (endure) params.endure = String(endure.Id);

  if (extra) {
    for (var key in extra) {
      if (!Object.prototype.hasOwnProperty.call(extra, key)) continue;
      var value = extra[key];
      if (value === undefined || value === null || value === "") continue;
      params[key] = String(value);
    }
  }

  var query = [];
  for (var name in params) {
    if (!Object.prototype.hasOwnProperty.call(params, name)) continue;
    if (name === "subcategory_id" && params[name] === "0") continue;
    var encoded =
      name === "page" ? params[name] : encodeURIComponent(params[name]);
    query.push(name + "=" + encoded);
  }
  return XY_API_ROOT + "ranking.php?" + query.join("&");
}

function xyAddTagChips(rows, config, state) {
  var groups = xyOptions(xyConfigLine(config.lines, "classid"));
  if (!groups.length) return;
  xyHeader(rows, "标签筛选 · 单选");
  for (var groupIndex = 0; groupIndex < groups.length; groupIndex++) {
    var group = groups[groupIndex];
    var tags = group.Extvalue || [];
    if (!tags.length) continue;
    xyHeader(rows, String(group.Name));
    for (var tagIndex = 0; tagIndex < tags.length; tagIndex++) {
      var tag = tags[tagIndex];
      var value = String(group.Id) + ":" + String(tag.Id);
      var selected = String(state.xyTagValue) === value;
      var next = xyWithState(state, "xyTagValue", selected ? "" : value);
      xyChip(
        rows,
        String(tag.Name),
        xyRankingUrl(config, next, "{{page}}"),
        selected,
      );
    }
  }
}

function xySquareSiteId(state) {
  return xySiteIdByName(state.xySite) === 12 ? 12 : 11;
}

function xySquareJumpQuery(jumpUrl) {
  var text = String(jumpUrl || "");
  var match = text.match(/[?&]query=([^&]+)/i);
  if (!match) return {};
  var raw = match[1];
  try {
    if (raw.indexOf("%7B") === 0 || raw.indexOf("%7b") === 0)
      raw = decodeURIComponent(raw);
    var parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    return {};
  }
}

function xySquareRankingUrl(siteId, order, filter, category, page) {
  var params = {
    action: "ranking",
    site_id: String(siteId),
    order: String(order),
    page: String(page),
    page_size: "20",
  };
  if (
    category !== undefined &&
    category !== null &&
    String(category) !== "-1"
  ) {
    params.category_id = String(category);
  }
  if (filter) params.filter = String(filter).replace(/=/g, ":");
  var query = [];
  for (var name in params) {
    if (!Object.prototype.hasOwnProperty.call(params, name)) continue;
    query.push(
      name +
        "=" +
        (name === "page" ? params[name] : encodeURIComponent(params[name])),
    );
  }
  return XY_API_ROOT + "ranking.php?" + query.join("&");
}

function xySquareListUrl(itemId, page) {
  return (
    XY_API_ROOT +
    "ranking.php?action=list&item_id=" +
    encodeURIComponent(String(itemId)) +
    "&page=" +
    page +
    "&page_size=100"
  );
}

function xySquareBlockUrl(name, data, state) {
  var siteId = xySquareSiteId(state);
  var title = data.Title || {};
  var common = data.CommonExt || {};
  var query = xySquareJumpQuery(title.JumpActionUrl);
  var lowerName = String(name || "").toLowerCase();
  var column = String(common.ColumnName || "");
  if (query.itemId !== undefined && query.itemId !== null) {
    return xySquareListUrl(query.itemId, "{{page}}");
  }
  if (query.filter !== undefined && query.filter !== null) {
    return xySquareRankingUrl(
      siteId,
      1,
      query.filter,
      query.categoryId,
      "{{page}}",
    );
  }
  if (
    String(title.JumpActionUrl || "").indexOf("SanJiang") >= 0 ||
    lowerName.indexOf("新书") >= 0 ||
    lowerName.indexOf("潜力") >= 0 ||
    column.indexOf("xinshu") >= 0
  ) {
    return xySquareRankingUrl(siteId, 15, "", query.categoryId, "{{page}}");
  }
  if (lowerName.indexOf("免费") >= 0) {
    return xySquareRankingUrl(siteId, 11, "paidmode:1", 0, "{{page}}");
  }
  if (lowerName.indexOf("完本") >= 0) {
    return xySquareRankingUrl(siteId, 11, "actionstatus:1", 0, "{{page}}");
  }
  return xySquareRankingUrl(siteId, 11, "", query.categoryId, "{{page}}");
}

function xyLoadSquare(ctx, state) {
  var sourceSiteId = xySiteIdByName(state.xySite);
  if (sourceSiteId !== 11 && sourceSiteId !== 12) return [];
  var siteId = xySquareSiteId(state);
  var blocks = [];
  try {
    var response = xyJson(
      ctx,
    XY_API_ROOT +
        "ranking.php?action=square&site=" +
        siteId +
        "&page=1&page_size=20",
    );
    var resultCode =
      response.Result !== undefined
        ? Number(response.Result)
        : Number(response.result || 0);
    var items = (response.Data || response.data || {}).Items || [];
    if (resultCode !== 0 || !items.length) return blocks;
    for (var index = 0; index < items.length; index++) {
      var data = items[index].Data || {};
      var name = String((data.Title || {}).Name || "").replace(
        /^\s+|\s+$/g,
        "",
      );
      if (!name) continue;
      var hasBooks = false;
      var listKeys = ["List", "BookList", "DataList", "Items", "ItemList"];
      for (var keyIndex = 0; keyIndex < listKeys.length; keyIndex++) {
        var value = data[listKeys[keyIndex]];
        if (value && value.length) hasBooks = true;
      }
      if (!hasBooks) continue;
      blocks.push({ name: name, url: xySquareBlockUrl(name, data, state) });
    }
  } catch (error) {
    try {
      xyBridge(ctx).log("起点书城分块加载失败：" + error);
    } catch (ignored) {}
  }
  return blocks;
}

function xyAddSquareBlocks(ctx, rows, state) {
  var blocks = xyLoadSquare(ctx, state);
  if (!blocks.length) return;
  xyHeader(rows, "起点书城 · " + state.xySite);
  for (var index = 0; index < blocks.length; index++) {
    xyChip(rows, blocks[index].name, blocks[index].url, false);
  }
}

function xyExplore(ctx) {
  var state = xyState(ctx);
  var config = xyLoadConfig(ctx, state);
  var categoryLine = xyConfigLine(config.lines, "categoryid");
  var categories = xyOptions(categoryLine);
  var site = xySelected(config.sites, state.xySite);
  var order = xySelected(config.orders, state.xyOrderName);
  var category = xySelected(categories, state.xyCategoryName);
  var actionStatusLine = xyConfigLine(config.lines, "actionstatus");
  var wordsCountLine = xyConfigLine(config.lines, "wordscount");
  var paidModeLine = xyConfigLine(config.lines, "paidmode");
  var tagTypeLine = xyConfigLine(config.lines, "tagtype");
  var rows = [];

  xyAddSquareBlocks(ctx, rows, state);
  xyHeader(rows, "主筛选 · 起点发现");
  xySelect(
    rows,
    "站点",
    config.sites,
    site,
    xySelectAction("xySite", "站点", ["xyCategoryName", "xySubCategoryName"], {
      分类: "全部",
      子分类: null,
    }),
    "站点",
  );
  xySelect(
    rows,
    "榜单",
    config.orders,
    order,
    xySelectAction("xyOrderName", "榜单"),
    "榜单",
  );
  xySelect(
    rows,
    "分类",
    categories,
    category,
    xySelectAction("xyCategoryName", "分类", ["xySubCategoryName"], {
      子分类: null,
    }),
    "分类",
  );
  var subcategoryOptions = xyBlankOptions(
    (category && category.Extvalue) || [],
  );
  if (subcategoryOptions.length > 1) {
    xySelect(
      rows,
      "子分类",
      subcategoryOptions,
      xySelected(subcategoryOptions, state.xySubCategoryName),
      xySelectAction("xySubCategoryName", "子分类"),
      "子类",
    );
  }
  xyActionButton(
    rows,
    "重置主筛选（恢复默认）",
    "xyResetMainExploreFilters(source, java, infoMap)",
    1,
  );

  xyHeader(rows, "扩展筛选");
  xySelect(
    rows,
    "连载状态",
    xyBlankOptions(xyOptions(actionStatusLine)),
    { Name: state.xyActionStatusName },
    xySelectAction("xyActionStatusName", "连载状态"),
    "状态",
  );
  xySelect(
    rows,
    "字数范围",
    xyBlankOptions(xyOptions(wordsCountLine)),
    { Name: state.xyWordsCountName },
    xySelectAction("xyWordsCountName", "字数范围"),
    "字数",
  );
  xySelect(
    rows,
    "付费模式",
    xyBlankOptions(xyOptions(paidModeLine)),
    { Name: state.xyPaidModeName },
    xySelectAction("xyPaidModeName", "付费模式"),
    "付费",
  );
  xySelect(
    rows,
    "标签匹配",
    xyOptions(tagTypeLine),
    { Name: state.xyTagTypeName },
    xySelectAction("xyTagTypeName", "标签匹配"),
    "匹配",
  );
  xySelect(
    rows,
    "精品",
    xyBlankOptions(xyOptions(xyConfigLine(config.filterOne, "great"))),
    { Name: state.xyGreatName },
    xySelectAction("xyGreatName", "精品"),
    "精品",
  );
  xySelect(
    rows,
    "耐看",
    xyBlankOptions(xyOptions(xyConfigLine(config.filterOne, "endure"))),
    { Name: state.xyEndureName },
    xySelectAction("xyEndureName", "耐看"),
    "耐看",
  );
  xyActionButton(
    rows,
    "重置扩展筛选",
    "xyResetExtendedExploreFilters(source, java, infoMap)",
    1,
  );

  xyHeader(rows, "结果操作");
  xyEntry(rows, "当前结果", xyRankingUrl(config, state, "{{page}}"), 1);

  xyAddTagChips(rows, config, state);

  if (!config.valid) {
    xyHeader(rows, "配置接口暂不可用，当前使用默认榜单");
  }
  return JSON.stringify(rows);
}

